CREATE TABLE transportistas(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,telefono VARCHAR(20),activo BOOLEAN NOT NULL);
CREATE TABLE zonas(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,ciudad VARCHAR(100) NOT NULL,activo BOOLEAN NOT NULL);
CREATE TABLE coberturas(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_transportista BIGINT NOT NULL REFERENCES transportistas(id),id_zona BIGINT NOT NULL REFERENCES zonas(id),tarifa NUMERIC(10,2) NOT NULL CHECK(tarifa>=0),dias_estimados INTEGER NOT NULL CHECK(dias_estimados BETWEEN 1 AND 30),activo BOOLEAN NOT NULL,UNIQUE(id_transportista,id_zona));
